<?php require 'db.php'; header('Content-Type: application/json; charset=utf-8'); try{$a=$_POST['accion']??$_GET['accion']??'listar'; if($a==='listar'){$s=$pdo->query('SELECT b.*,s.nombre socio_nombre,s.apellidos socio_apellidos FROM barcos b LEFT JOIN Socios s ON s.documento=b.Socios_documento ORDER BY b.no_matricula');echo json_encode(['ok'=>true,'datos'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE);exit;} if($a==='crear'){$s=$pdo->prepare('INSERT INTO barcos(no_matricula,nombre,cuota,no_amarre,Socios_documento) VALUES(?,?,?,?,?)');$s->execute([$_POST['no_matricula'],trim($_POST['nombre']),$_POST['cuota']!==''?$_POST['cuota']:null,$_POST['no_amarre']!==''?$_POST['no_amarre']:null,trim($_POST['Socios_documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Barco creado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='actualizar'){$s=$pdo->prepare('UPDATE barcos SET nombre=?,cuota=?,no_amarre=?,Socios_documento=? WHERE no_matricula=?');$s->execute([trim($_POST['nombre']),$_POST['cuota']!==''?$_POST['cuota']:null,$_POST['no_amarre']!==''?$_POST['no_amarre']:null,trim($_POST['Socios_documento']),$_POST['no_matricula']]);echo json_encode(['ok'=>true,'mensaje'=>'Barco actualizado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='eliminar'){$s=$pdo->prepare('DELETE FROM barcos WHERE no_matricula=?');$s->execute([$_POST['no_matricula']]);echo json_encode(['ok'=>true,'mensaje'=>'Barco eliminado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>'Acción no válida.'],JSON_UNESCAPED_UNICODE);}catch(PDOException $e){http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
?>
